1|"use client";
2|
3|import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4|import {
5|  CHOPIN_PLAYLIST_ID,
6|  nextTrack,
7|  parseManifest,
8|  resolveInitialSelection,
9|  styleHasTracks,
10|} from "@/core/music";
11|import type { MusicManifest, MusicSelection, SceneSignal, Track } from "@/core/music";
12|import {
13|  enterPlaylist,
14|  exitPlaylist,
15|  initScheduler,
16|  noteTrackEnded,
17|  observeScene,
18|  requestNext,
19|  switchStyle,
20|  tickScheduler,
21|} from "@/core/music-schedule";
22|import type { SchedulerState } from "@/core/music-schedule";
23|import { pickActiveScene } from "./active-scene";
24|import { loadMusicPrefs, saveMusicPrefs } from "./music-prefs";
25|import { mixOffSelection, styleSelection } from "./music-transitions";
26|import { Player } from "./player";
27|
28|export interface SceneMeta {
29|  id: string;
30|  title: string;
31|  emotion: SceneSignal | null;
32|}
33|
34|// The Chopin playlist, when the manifest defines it with tracks. The
35|// button stays hidden otherwise, and the player never persists the mode.
36|function findChopinPlaylist(manifest: MusicManifest) {
37|  const found = manifest.playlists.find((p) => p.id === CHOPIN_PLAYLIST_ID) ?? null;
38|  return found && found.trackIds.length > 0 ? found : null;
39|}
40|
41|// Client container: tracks the active scene, runs the pure scheduler
42|// with wall-clock seconds, and passes the chosen track to the player.
43|export function Reader({ scenes, children }: { scenes: SceneMeta[]; children: React.ReactNode }) {
44|  const [activeId, setActiveId] = useState<string | null>(scenes[0]?.id ?? null);
45|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
46|  const [selection, setSelection] = useState<MusicSelection | null>(null);
47|  const [musicFailed, setMusicFailed] = useState(false);
48|  const [currentId, setCurrentId] = useState<string | null>(null);
49|  const [replayNonce, setReplayNonce] = useState(0);
50|  const [fadeSec, setFadeSec] = useState(0);
51|  const [isFallback, setIsFallback] = useState(false);
52|  const [playlistOn, setPlaylistOn] = useState(false);
53|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s])), [scenes]);
54|  const schedRef = useRef<SchedulerState>(initScheduler());
55|  const liveRef = useRef({ activeId, manifest, selection, currentId, byId, playlistOn });
56|  liveRef.current = { activeId, manifest, selection, currentId, byId, playlistOn };
57|
58|  const nowSec = () => Date.now() / 1000;
59|
60|  const applyDecision = useCallback((decision: {
61|    state: SchedulerState;
62|    switchToId: string | null;
63|    crossfadeSec: number;
64|    fallback: boolean;
65|  }) => {
66|    // A same-id switch (one-track playlist wrap) bails out of setCurrentId,
67|    // so bump a replay nonce the player effect listens to instead.
68|    const prevId = schedRef.current.currentId;
69|    schedRef.current = decision.state;
70|    setActiveId(decision.state.activeSceneId);
71|    setIsFallback(decision.fallback);
72|    if (decision.switchToId !== null) {
73|      setFadeSec(decision.crossfadeSec);
74|      if (decision.switchToId === prevId) {
75|        setReplayNonce((n) => n + 1);
76|      } else {
77|        setCurrentId(decision.switchToId);
78|      }
79|    }
80|  }, []);
81|
82|  const persist = useCallback((next: MusicSelection) => {
83|    setSelection(next);
84|    saveMusicPrefs({
85|      mode: next.mode,
86|      soundtrackId: next.soundtrackId,
87|      style: next.style,
88|    });
89|  }, []);
90|
91|  const observe = useCallback(
92|    (sceneId: string) => {
93|      const st = liveRef.current;
94|      if (!st.manifest || !st.selection) return;
95|      const signal = st.byId.get(sceneId)?.emotion ?? null;
96|      applyDecision(
97|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
98|          selection: st.selection,
99|          rng: Math.random,
100|        }),
101|      );
102|    },
103|    [applyDecision],
104|  );
105|
106|  useEffect(() => {
107|    let cancelled = false;
108|    fetch("/music/manifest.json")
109|      .then((res) => {
110|        if (!res.ok) throw new Error(`manifest ${res.status}`);
111|        return res.json();
112|      })
113|      .then((json: unknown) => {
114|        if (cancelled) return;
115|        const parsed = parseManifest(json);
116|        setManifest(parsed);
117|        setSelection(resolveInitialSelection(parsed, loadMusicPrefs()));
118|      })
119|      .catch(() => {
120|        if (!cancelled) setMusicFailed(true);
121|      });
122|    return () => {
123|      cancelled = true;
124|    };
125|  }, []);
126|
127|  // Reselect once the manifest lands so the first scene gets music.
128|  useEffect(() => {
129|    if (!manifest) return;
130|    const st = liveRef.current;
131|    if (st.activeId) observe(st.activeId);
132|  }, [manifest, observe]);
133|
134|  useEffect(() => {
135|    const snapshot = () =>
136|      [...document.querySelectorAll<HTMLElement>("section[data-scene-id]")].map((el) => ({
137|        id: el.dataset.sceneId ?? "",
138|        top: el.getBoundingClientRect().top,
139|      }));
140|    const readActive = () => pickActiveScene(snapshot(), window.innerHeight / 3);
141|    const observer = new IntersectionObserver(
142|      () => {
143|        // Entries are only a trigger; every callback re-snapshots live rects.
144|        const next = readActive();
145|        if (next) observe(next);
146|      },
147|      { rootMargin: "-30% 0px -65% 0px" },
148|    );
149|    document.querySelectorAll("section[data-scene-id]").forEach((el) => observer.observe(el));
150|    const first = readActive();
151|    if (first) observe(first);
152|    const timer = window.setInterval(() => {
153|      // Settle an expired dwell, or re-check the active scene after a hold.
154|      const st = liveRef.current;
155|      if (!st.manifest || !st.selection || !st.activeId) return;
156|      const sceneId = schedRef.current.pendingSceneId ?? st.activeId;
157|      const signal = st.byId.get(sceneId)?.emotion ?? null;
158|      applyDecision(
159|        tickScheduler(schedRef.current, signal, st.manifest, nowSec(), {
160|          selection: st.selection,
161|          rng: Math.random,
162|        }),
163|      );
164|    }, 1000);
165|    return () => {
166|      observer.disconnect();
167|      window.clearInterval(timer);
168|    };
169|  }, [observe, applyDecision]);
170|
171|  function skip() {
172|    const st = liveRef.current;
173|    if (!st.manifest || !st.selection || !st.activeId) return;
174|    const signal = st.byId.get(st.activeId)?.emotion ?? null;
175|    applyDecision(
176|      requestNext(schedRef.current, signal, st.manifest, nowSec(), {
177|        selection: st.selection,
178|        rng: Math.random,
179|      }),
180|    );
181|  }
182|
183|  function togglePlaylist() {
184|    const st = liveRef.current;
185|    if (!st.manifest || !st.selection) return;
186|    const playlist = findChopinPlaylist(st.manifest);
187|    if (!playlist) return;
188|    if (st.playlistOn) {
189|      const signal = (st.activeId && st.byId.get(st.activeId)?.emotion) || null;
190|      applyDecision(
191|        exitPlaylist(schedRef.current, signal ?? null, st.manifest, nowSec(), {
192|          selection: st.selection,
193|          rng: Math.random,
194|        }),
195|      );
196|      setPlaylistOn(false);
197|      return;
198|    }
199|    applyDecision(enterPlaylist(schedRef.current, st.manifest, playlist.id, nowSec()));
200|    setPlaylistOn(true);
201|  }
202|
203|  function toggleMix() {
204|    const st = liveRef.current;
205|    if (!st.manifest || !st.selection || st.playlistOn) return;
206|    if (st.selection.mode === "random") {
207|      // Mixing off keeps the soundtrack of the playing track.
208|      const playing = st.manifest.tracks.find((t) => t.id === st.currentId) ?? null;
209|      persist(mixOffSelection(st.selection, playing));
210|      return;
211|    }
212|    persist({ ...st.selection, mode: "random" });
213|  }
214|
215|  function changeStyle(style: string) {
216|    const st = liveRef.current;
217|    if (!st.manifest || !st.selection || !st.activeId || st.playlistOn) return;
218|    if (style === st.selection.style) return;
219|    const signal = st.byId.get(st.activeId)?.emotion ?? null;
220|    const decision = switchStyle(schedRef.current, signal, st.manifest, nowSec(), style);
221|    if (decision.soundtrackId === null) return;
222|    applyDecision(decision);
223|    persist(styleSelection(st.selection, style, decision.soundtrackId));
224|  }
225|
226|  function ended(trackId: string) {
227|    const st = liveRef.current;
228|    if (!st.manifest || !st.selection || !st.activeId) return;
229|    const signal = st.byId.get(st.activeId)?.emotion ?? null;
230|    applyDecision(
231|      noteTrackEnded(schedRef.current, signal, st.manifest, trackId, nowSec(), {
232|        selection: st.selection,
233|        rng: Math.random,
234|      }),
235|    );
236|  }
237|
238|  const track: Track | null = manifest?.tracks.find((t) => t.id === currentId) ?? null;
239|  const sceneTitle = (activeId && byId.get(activeId)?.title) || null;
240|  const empty = manifest !== null && manifest.tracks.length === 0;
241|  const activeSignal = (activeId && byId.get(activeId)?.emotion) || null;
242|  const soundtrackName =
243|    manifest?.soundtracks.find((s) => s.id === track?.soundtrack)?.name ?? null;
244|  // Styles with at least one emotion-selectable track; hidden while fewer
245|  // than two qualify.
246|  const stylesWithTracks =
247|    manifest?.styles.filter((s) => styleHasTracks(manifest, s.id)) ?? [];
248|  const activePlaylist = manifest ? findChopinPlaylist(manifest) : null;
249|  const canSkip =
250|    manifest !== null &&
251|    selection !== null &&
252|    (playlistOn
253|      ? (activePlaylist?.trackIds.length ?? 0) > 1
254|      : manifest.tracks.length > 1 &&
255|        nextTrack(activeSignal ?? null, manifest, currentId, undefined, selection) !== null);
256|
257|  return (
258|    <>
259|      <div className="player-bar">
260|        {musicFailed || empty ? (
261|          <p className="player-note">Music unavailable. The reader works without it.</p>
262|        ) : (
263|          <Player
264|            track={track}
265|            replayNonce={replayNonce}
266|            fadeSec={fadeSec}
267|            sceneTitle={sceneTitle}
268|            soundtrackName={soundtrackName}
269|            isFallback={isFallback}
270|            canSkip={canSkip}
271|            onSkip={skip}
272|            mixOn={selection?.mode === "random"}
273|            onToggleMix={toggleMix}
274|            styles={stylesWithTracks}
275|            styleId={selection?.style ?? null}
276|            onStyleChange={changeStyle}
277|            onEnded={ended}
278|            playlistOn={playlistOn}
279|            playlistLabel={activePlaylist?.label ?? null}
280|            onTogglePlaylist={togglePlaylist}
281|            controlsDisabled={playlistOn}
282|          />
283|        )}
284|      </div>
285|      {children}
286|    </>
287|  );
288|}

