24|async function postImage(body: unknown): Promise<ImageResponse> {
25|  const res = await fetch("/api/images", {
26|    method: "POST",
27|    headers: { "Content-Type": "application/json" },
28|    body: JSON.stringify(body),
29|  });
30|  return (await res.json()) as ImageResponse;
