33|// Companion panel: illustrates the selected passage or the current scene.
34|// The client sends ordinals and ids only, never text.
35|export function PicturePanel({ bookId, textVersion }: { bookId: string; textVersion: string }) {
36|  const [card, setCard] = useState<Card>({ phase: "idle" });
37|  const [selTop, setSelTop] = useState<number | null>(null);
38|  const [selLeft, setSelLeft] = useState<number | null>(null);
39|  const pollLeft = useRef(0);
40|
41|  const request = useCallback(
42|    async (body: unknown) => {
43|      setCard({ phase: "loading" });
44|      pollLeft.current = POLL_MAX;
45|      for (;;) {
46|        let res: ImageResponse;
47|        try {
48|          res = await postImage(body);
49|        } catch {
50|          setCard({ phase: "error", message: "No se pudo generar la imagen. Vuelve a intentarlo." });
51|          return;
52|        }
53|        if (res.status === "ready") {
54|          setCard({ phase: "ready", url: res.url, caption: res.caption, cached: res.cached });
55|          return;
56|        }
57|        if (res.status === "error") {
58|          setCard({ phase: "error", message: res.message });
59|          return;
60|        }
61|        pollLeft.current -= 1;
62|        if (pollLeft.current <= 0) {
63|          setCard({
64|            phase: "error",
65|            message: "La imagen tarda más de lo esperado. Vuelve a intentarlo.",
66|          });
67|          return;
68|        }
69|        await new Promise((done) => setTimeout(done, POLL_MS));
70|      }
71|    },
72|    [],
73|  );
74|
75|  useEffect(() => {
76|    const onChange = () => {
77|      const sel = window.getSelection();
78|      const book = document.querySelector("main.book");
79|      if (!sel || sel.isCollapsed || !book || !sel.rangeCount) {
80|        setSelTop(null);
81|        return;
82|      }
83|      if (!book.contains(sel.anchorNode) && !book.contains(sel.focusNode)) {
84|        setSelTop(null);
85|        return;
86|      }
87|      const rect = sel.getRangeAt(0).getBoundingClientRect();
88|      setSelTop(rect.top + window.scrollY - 44);
89|      setSelLeft(Math.min(rect.left + window.scrollX, window.scrollX + window.innerWidth - 220));
90|    };
