97|    const book = document.querySelector("main.book");
98|    if (!sel || !book) return;
99|    const entries: ParaEntry[] = [...book.querySelectorAll("p[id][data-n]")].map((el) => ({
100|      id: el.id,
101|      n: Number(el.getAttribute("data-n")),
102|    }));
103|    const n = pickStartN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
104|    setSelTop(null);
105|    if (n === null || !Number.isInteger(n)) return;
106|    void request({ kind: "passage", bookId, textVersion, n });
107|  }, [bookId, textVersion, request]);
108|
109|  const illustrateScene = useCallback(() => {
110|    const sections = [...document.querySelectorAll<HTMLElement>("section[data-scene-id]")].map(
111|      (el) => ({ id: el.dataset.sceneId ?? "", top: el.getBoundingClientRect().top }),
112|    );
113|    const sceneId = pickActiveScene(sections, window.innerHeight / 3);
114|    if (!sceneId) return;
115|    void request({ kind: "scene", bookId, textVersion, sceneId });
116|  }, [bookId, textVersion, request]);
117|
118|  return (
119|    <div className="picture">
