121|        Ilustrar escena
122|      </button>
123|      {card.phase === "ready" ? (
124|        <figure className="picture-card">
125|          <img src={card.url} alt={card.caption} className="picture-img" />
126|          <figcaption>
127|            {card.caption} <span className="picture-flag">{card.cached ? "Guardada" : "Nueva"}</span>
128|          </figcaption>
129|        </figure>
130|      ) : card.phase === "loading" ? (
131|        <div className="picture-loading" role="status" aria-label="Ilustrando">
132|          Ilustrando…
133|        </div>
134|      ) : card.phase === "error" ? (
135|        <p className="picture-error" role="alert">
136|          {card.message}
137|        </p>
138|      ) : null}
139|      <p className="picture-note">El chat llega más adelante.</p>
140|      {selTop !== null && selLeft !== null ? (
141|        <button
142|          type="button"
143|          className="picture-float"
144|          style={{ top: selTop, left: selLeft }}
145|          onClick={illustratePassage}
146|          aria-label="Ilustrar este pasaje"
147|        >
148|          Ilustrar este pasaje
149|        </button>
150|      ) : null}
151|    </div>
152|  );
