1|// Pure music scheduler. The reader calls it with explicit nowSec values,
2|// so dwell, hysteresis, and hard cuts are testable without timers.
3|import {
4|  MUSIC_CONFIG,
5|  candidatesFor,
6|  dominantEmotion,
7|  homeTracks,
8|  nextTrack,
9|  pickRandomTrack,
10|  requestStyleChange,
11|  rankTracks,
12|  resolveConfig,
13|  scoreTrack,
14|} from "./music";
15|import type { MusicConfig, MusicManifest, SceneSignal, SelectEnv, Track } from "./music";
16|
17|export interface SchedulerState {
18|  currentId: string | null;
19|  currentStartedSec: number;
20|  activeSceneId: string | null;
21|  pendingSceneId: string | null;
22|  pendingSinceSec: number;
23|  overrideId: string | null;
24|  overrideSceneId: string | null;
25|  playlist: { id: string; index: number } | null;
26|}
27|
28|export interface ScheduleDecision {
29|  state: SchedulerState;
30|  switchToId: string | null;
31|  crossfadeSec: number;
32|  hardCut: boolean;
33|  fallback: boolean;
34|}
35|
36|export interface StyleSwitchDecision extends ScheduleDecision {
37|  soundtrackId: string | null;
38|}
39|
40|export function initScheduler(): SchedulerState {
41|  return {
42|    currentId: null,
43|    currentStartedSec: 0,
44|    activeSceneId: null,
45|    pendingSceneId: null,
46|    pendingSinceSec: 0,
47|    overrideId: null,
48|    overrideSceneId: null,
49|    playlist: null,
50|  };
51|}
52|
53|function noChange(state: SchedulerState): ScheduleDecision {
54|  return { state, switchToId: null, crossfadeSec: 0, hardCut: false, fallback: false };
55|}
56|
57|function topRanked(
58|  signal: SceneSignal | null,
59|  manifest: MusicManifest,
60|  config: MusicConfig,
61|  excludeId?: string | null,
62|): { id: string; score: number } | null {
63|  if (signal === null) {
64|    const ids = [...manifest.tracks]
65|      .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
66|      .filter((t) => t.id !== excludeId);
67|    const first = ids[0];
68|    return first ? { id: first.id, score: 0 } : null;
69|  }
70|  const ranked = rankTracks(signal, manifest, config).filter((t) => t.id !== excludeId);
71|  const best = ranked[0];
72|  return best ? { id: best.id, score: scoreTrack(signal, best, config) } : null;
73|}
74|
75|// Pick the switch for a newly active scene: best score wins, but the
76|// current track holds unless the best beats it by switchMargin after
77|// minTrackSec, or by hardCutMargin at once (hard cut, short fade).
78|function gatedEvaluate(
79|  state: SchedulerState,
80|  signal: SceneSignal,
81|  scoped: MusicManifest,
82|  nowSec: number,
83|  config: MusicConfig,
84|): ScheduleDecision {
85|  const best = topRanked(signal, scoped, config);
86|  if (!best) return noChange(state);
87|  const current = scoped.tracks.find((t) => t.id === state.currentId) ?? null;
88|  if (!current || best.id === current.id) {
89|    if (!current) {
90|      return {
91|        state: { ...state, currentId: best.id, currentStartedSec: nowSec },
92|        switchToId: best.id,
93|        crossfadeSec: 0,
94|        hardCut: false,
95|        fallback: false,
96|      };
97|    }
98|    return noChange(state);
99|  }
100|  const gap = best.score - scoreTrack(signal, current, config);
101|  if (gap >= config.hardCutMargin) {
102|    return {
103|      state: { ...state, currentId: best.id, currentStartedSec: nowSec },
104|      switchToId: best.id,
105|      crossfadeSec: config.hardCutCrossfadeSec,
106|      hardCut: true,
107|      fallback: false,
108|    };
109|  }
110|  if (gap >= config.switchMargin && nowSec - state.currentStartedSec >= config.minTrackSec) {
111|    return {
112|      state: { ...state, currentId: best.id, currentStartedSec: nowSec },
113|      switchToId: best.id,
114|      crossfadeSec: config.crossfadeSec,
115|      hardCut: false,
116|      fallback: false,
117|    };
118|  }
119|  return noChange(state);
120|}
121|
122|// Random mode pick on a scheduled select: the draw keeps the current
123|// track when it is eligible, so rescans do not churn. Dwell is handled
124|// by promotion; min-track holds the current pick.
125|function evaluateRandom(
126|  state: SchedulerState,
127|  signal: SceneSignal,
128|  styleTracks: Track[],
129|  scoped: MusicManifest,
130|  nowSec: number,
131|  config: MusicConfig,
132|  env: SelectEnv,
133|): ScheduleDecision {
134|  const pick = pickRandomTrack(styleTracks, signal, state.currentId, env.rng, config);
135|  if (!pick || pick.id === state.currentId) return noChange(state);
136|  if (state.currentId !== null && nowSec - state.currentStartedSec < config.minTrackSec) {
137|    return noChange(state);
138|  }
139|  return {
140|    state: { ...state, currentId: pick.id, currentStartedSec: nowSec },
141|    switchToId: pick.id,
142|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
143|    hardCut: false,
144|    fallback: false,
145|  };
146|}
147|
148|function evaluateSwitch(
149|  state: SchedulerState,
150|  signal: SceneSignal | null,
151|  manifest: MusicManifest,
152|  nowSec: number,
153|  config: MusicConfig,
154|  env: SelectEnv,
155|): ScheduleDecision {
156|  if (signal === null) return noChange(state);
157|  if (state.playlist !== null) return noChange(state);
158|  const styleTracks = candidatesFor(env.selection, manifest);
159|  if (styleTracks.length === 0) return noChange(state);
160|  const scoped = { ...manifest, tracks: styleTracks };
161|  if (env.selection.mode === "random") {
162|    return evaluateRandom(state, signal, styleTracks, scoped, nowSec, config, env);
163|  }
164|  const home = homeTracks(env.selection, styleTracks);
165|  const dom = dominantEmotion(signal);
166|  // Per-scene fallback: when the home soundtrack has no track with the
167|  // scene emotion, borrow the best same-style track for this scene only.
168|  const emo = styleTracks.filter((t) => t.emotion === dom);
169|  const scope = home.some((t) => t.emotion === dom) ? home : emo.length > 0 ? emo : styleTracks;
170|  const decision = gatedEvaluate(state, signal, { ...manifest, tracks: scope }, nowSec, config);
171|  if (decision.switchToId === null) return decision;
172|  const inside = home.some((t) => t.id === decision.switchToId);
173|  // A fallback pick misses the current track in its scope, which reads
174|  // as a first play with no fade. Restore the normal crossfade then.
175|  if (decision.crossfadeSec === 0 && state.currentId !== null) {
176|    return { ...decision, crossfadeSec: config.crossfadeSec, fallback: !inside };
177|  }
178|  return { ...decision, fallback: !inside };
179|}
180|
181|function promote(
182|  state: SchedulerState,
183|  sceneId: string,
184|  signal: SceneSignal | null,
185|  manifest: MusicManifest,
186|  nowSec: number,
187|  config: MusicConfig,
188|  env: SelectEnv,
189|): ScheduleDecision {
190|  const settled: SchedulerState = {
191|    ...state,
192|    activeSceneId: sceneId,
193|    pendingSceneId: null,
194|    pendingSinceSec: 0,
195|    overrideId: null,
196|    overrideSceneId: null,
197|  };
198|  const decision = evaluateSwitch(settled, signal, manifest, nowSec, config, env);
199|  return { ...decision, state: { ...decision.state, activeSceneId: sceneId } };
200|}
201|
202|// The reading position entered a scene. It becomes pending and the dwell
203|// clock restarts, so fast scrolling keeps only the newest scene. After
204|// the pending scene holds for dwellSec it becomes active. The first
205|// track ever plays at once, with no dwell.
206|export function observeScene(
207|  state: SchedulerState,
208|  sceneId: string,
209|  signal: SceneSignal | null,
210|  manifest: MusicManifest,
211|  nowSec: number,
212|  env: SelectEnv,
213|  override?: Partial<MusicConfig>,
214|): ScheduleDecision {
215|  const config = resolveConfig(override ?? MUSIC_CONFIG);
216|  if (state.currentId === null) {
217|    return promote(state, sceneId, signal, manifest, nowSec, config, env);
218|  }
219|  if (sceneId === state.activeSceneId) {
220|    return noChange({ ...state, pendingSceneId: null, pendingSinceSec: 0 });
221|  }
222|  if (sceneId !== state.pendingSceneId) {
223|    return noChange({ ...state, pendingSceneId: sceneId, pendingSinceSec: nowSec });
224|  }
225|  if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
226|  return promote(state, sceneId, signal, manifest, nowSec, config, env);
227|}
228|
229|// Time passed: settle a pending scene whose dwell has expired, or
230|// re-check the active scene (a hold from minTrackSec may have expired).
231|// The reader passes the pending signal when one exists, else the active.
232|export function tickScheduler(
233|  state: SchedulerState,
234|  signal: SceneSignal | null,
235|  manifest: MusicManifest,
236|  nowSec: number,
237|  env: SelectEnv,
238|  override?: Partial<MusicConfig>,
239|): ScheduleDecision {
240|  const config = resolveConfig(override ?? MUSIC_CONFIG);
241|  if (state.currentId === null) return noChange(state);
242|  if (state.pendingSceneId !== null) {
243|    if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
244|    return promote(state, state.pendingSceneId, signal, manifest, nowSec, config, env);
245|  }
246|  // A skip override holds until the next scene change; promotion clears it.
247|  if (state.overrideId !== null) return noChange(state);
248|  if (state.activeSceneId === null) return noChange(state);
249|  return evaluateSwitch(state, signal, manifest, nowSec, config, env);
250|}
251|
252|// Reader skip: the same-emotion Next rule, applied at once with the
253|// normal crossfade. The choice holds until the next scene change.
254|export function requestNext(
255|  state: SchedulerState,
256|  signal: SceneSignal | null,
257|  manifest: MusicManifest,
258|  nowSec: number,
259|  env: SelectEnv,
260|  override?: Partial<MusicConfig>,
261|): ScheduleDecision {
262|  const config = resolveConfig(override ?? MUSIC_CONFIG);
263|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
264|  const next = nextTrack(signal, manifest, state.currentId, config, env.selection);
265|  if (!next) return noChange(state);
266|  const home = homeTracks(env.selection, candidatesFor(env.selection, manifest));
267|  return {
268|    state: {
269|      ...state,
270|      currentId: next.id,
271|      currentStartedSec: nowSec,
272|      overrideId: next.id,
273|      overrideSceneId: state.activeSceneId,
274|    },
275|    switchToId: next.id,
276|    crossfadeSec: config.crossfadeSec,
277|    hardCut: false,
278|    fallback: env.selection.mode === "soundtrack" && !home.some((t) => t.id === next.id),
279|  };
280|}
281|
282|// A non-looping track ended: fade into the best remaining track,
283|// excluding the one that just ended. Never crosses styles.
284|export function noteTrackEnded(
285|  state: SchedulerState,
286|  signal: SceneSignal | null,
287|  manifest: MusicManifest,
288|  endedId: string,
289|  nowSec: number,
290|  env: SelectEnv,
291|  override?: Partial<MusicConfig>,
292|): ScheduleDecision {
293|  const config = resolveConfig(override ?? MUSIC_CONFIG);
294|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
295|  const styleTracks = candidatesFor(env.selection, manifest).filter((t) => t.id !== endedId);
296|  if (styleTracks.length === 0) return noChange(state);
297|  const best = topRanked(signal, { ...manifest, tracks: styleTracks }, config);
298|  if (!best) return noChange(state);
299|  const home = homeTracks(env.selection, candidatesFor(env.selection, manifest));
300|  return {
301|    state: {
302|      ...state,
303|      currentId: best.id,
304|      currentStartedSec: nowSec,
305|      overrideId: null,
306|      overrideSceneId: null,
307|    },
308|    switchToId: best.id,
309|    crossfadeSec: config.crossfadeSec,
310|    hardCut: false,
311|    fallback: env.selection.mode === "soundtrack" && !home.some((t) => t.id === best.id),
312|  };
313|}
314|
315|// Fixed playlist mode (the Chopin easter egg). Playlist order lives here
316|// because it reuses SchedulerState and the crossfade config.
317|function playlistById(manifest: MusicManifest, id: string) {
318|  return manifest.playlists.find((p) => p.id === id) ?? null;
319|}
320|
321|// Enter playlist mode: switch at once to the first track, with no dwell
322|// and no min-track rule. Scene changes stay tracked but never switch.
323|export function enterPlaylist(
324|  state: SchedulerState,
325|  manifest: MusicManifest,
326|  playlistId: string,
327|  nowSec: number,
328|  override?: Partial<MusicConfig>,
329|): ScheduleDecision {
330|  const config = resolveConfig(override ?? MUSIC_CONFIG);
331|  const playlist = playlistById(manifest, playlistId);
332|  const firstId = playlist?.trackIds[0];
333|  const first = firstId ? (manifest.tracks.find((t) => t.id === firstId) ?? null) : null;
334|  if (!playlist || !first) return noChange(state);
335|  return {
336|    state: {
337|      ...state,
338|      currentId: first.id,
339|      currentStartedSec: nowSec,
340|      overrideId: null,
341|      overrideSceneId: null,
342|      playlist: { id: playlist.id, index: 0 },
343|    },
344|    switchToId: first.id,
345|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
346|    hardCut: false,
347|    fallback: false,
348|  };
349|}
350|
351|// Next playlist track in trackIds order, wrapping last to first. Used by
352|// both the end-of-track path and the Next button while the playlist is on.
353|function advancePlaylist(
354|  state: SchedulerState,
355|  manifest: MusicManifest,
356|  nowSec: number,
357|  config: MusicConfig,
358|): ScheduleDecision {
359|  if (state.playlist === null) return noChange(state);
360|  const playlist = playlistById(manifest, state.playlist.id);
361|  if (!playlist || playlist.trackIds.length === 0) return noChange(state);
362|  // A one-track playlist wraps onto the same id. That still returns a
363|  // switch so the ended element re-cues instead of going quiet.
364|  const nextIndex = (state.playlist.index + 1) % playlist.trackIds.length;
365|  const nextId = playlist.trackIds[nextIndex];
366|  if (nextId === undefined) return noChange(state);
367|  const next = manifest.tracks.find((t) => t.id === nextId) ?? null;
368|  if (!next) return noChange(state);
369|  return {
370|    state: {
371|      ...state,
372|      currentId: next.id,
373|      currentStartedSec: nowSec,
374|      overrideId: null,
375|      overrideSceneId: null,
376|      playlist: { id: playlist.id, index: nextIndex },
377|    },
378|    switchToId: next.id,
379|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
380|    hardCut: false,
381|    fallback: false,
382|  };
383|}
384|
385|// Leave playlist mode: clear the playlist state and switch at once to the
386|// best match for the current scene under the restored selection.
387|export function exitPlaylist(
388|  state: SchedulerState,
389|  signal: SceneSignal | null,
390|  manifest: MusicManifest,
391|  nowSec: number,
392|  env: SelectEnv,
393|  override?: Partial<MusicConfig>,
394|): ScheduleDecision {
395|  if (state.playlist === null) return noChange(state);
396|  const config = resolveConfig(override ?? MUSIC_CONFIG);
397|  const styleTracks = candidatesFor(env.selection, manifest);
398|  const cleared: SchedulerState = {
399|    ...state,
400|    overrideId: null,
401|    overrideSceneId: null,
402|    playlist: null,
403|  };
404|  const best = topRanked(signal, { ...manifest, tracks: styleTracks }, config);
405|  if (!best) return { ...noChange(cleared), state: cleared };
406|  const home = homeTracks(env.selection, styleTracks);
407|  return {
408|    state: { ...cleared, currentId: best.id, currentStartedSec: nowSec },
409|    switchToId: best.id,
410|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
411|    hardCut: false,
412|    fallback: env.selection.mode === "soundtrack" && !home.some((t) => t.id === best.id),
413|  };
414|}
415|
416|// Style change from user action: switches at once with the normal
417|// crossfade, no dwell and no min-track rule, and sets the override like
418|// Next. Returns the new session soundtrack so the reader can store it.
419|export function switchStyle(
420|  state: SchedulerState,
421|  signal: SceneSignal | null,
422|  manifest: MusicManifest,
423|  nowSec: number,
424|  style: string,
425|  override?: Partial<MusicConfig>,
426|): StyleSwitchDecision {
427|  // The reader blocks style changes while a playlist plays. The guard
428|  // keeps the saved index pointing at the current track if one slips by.
429|  if (state.playlist !== null) return { ...noChange(state), soundtrackId: null };
430|  const config = resolveConfig(override ?? MUSIC_CONFIG);
431|  const picked = requestStyleChange(manifest, style, signal, config);
432|  if (!picked) return { ...noChange(state), soundtrackId: null };
433|  const home = manifest.tracks.filter(
434|    (t) => t.style === style && t.soundtrack === picked.soundtrackId,
435|  );
436|  return {
437|    state: {
438|      ...state,
439|      currentId: picked.track.id,
440|      currentStartedSec: nowSec,
441|      overrideId: picked.track.id,
442|      overrideSceneId: state.activeSceneId,
443|    },
444|    switchToId: picked.track.id,
445|    crossfadeSec: config.crossfadeSec,
446|    hardCut: false,
447|    fallback: !home.some((t) => t.id === picked.track.id),
448|    soundtrackId: picked.soundtrackId,
449|  };
450|}
451|
452|export { MUSIC_CONFIG };

