4|
5|const book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion"> = {
6|  id: "oz",
7|  textVersion: "v1",
8|  title: "Oz",
9|  author: "Baum",
10|  chapters: [
11|    { ch: 1, title: "One", start_n: 1, end_n: 3 },
12|    { ch: 2, title: "Two", start_n: 4, end_n: 5 },
13|  ],
14|  paragraphs: [
15|    { id: "c1p1", ch: 1, n: 1, text: "a" },
16|    { id: "c1p2", ch: 1, n: 2, text: "b" },
17|    { id: "c1p3", ch: 1, n: 3, text: "c" },
18|    { id: "c2p1", ch: 2, n: 4, text: "d" },
19|    { id: "c2p2", ch: 2, n: 5, text: "e" },
20|  ],
21|};
22|
23|function scene(over: Partial<AnalyzedScene> & { id: string }): AnalyzedScene {
24|  return {
25|    start_n: 1,
26|    end_n: 1,
27|    title: "S",
28|    summary: "",
29|    characters: [],
30|    ch: 1,
31|    jev: null,
32|    muse_override: null,
33|    final: null,
34|    error: null,
35|    ...over,
36|  };
37|}
38|
39|const scenes: AnalyzedScene[] = [
40|  scene({ id: "c1s1", start_n: 1, end_n: 2, final: null, error: "boom" }),
41|  scene({
42|    id: "c1s2",
43|    start_n: 3,
44|    end_n: 3,
45|    final: { vector: { calma: 1, alegria: 0, tristeza: 0, suspenso: 0, misterio: 0, aventura: 0, combate: 0, asombro: 0 }, intensity: 0.2, tempo: 0.3 },
46|  }),
47|  scene({ id: "c2s1", ch: 2, start_n: 4, end_n: 5, final: null, error: "boom" }),
48|];
49|
50|describe("buildReaderModel", () => {
51|  it("builds chapters in reading order with every paragraph once", () => {
52|    const model = buildReaderModel(book, { scenes });
53|    expect(model.bookId).toBe("oz");
54|    expect(model.chapters.map((c) => c.ch)).toEqual([1, 2]);
55|    expect(model.chapters.flatMap((c) => c.scenes).map((s) => s.id)).toEqual(["c1s1", "c1s2", "c2s1"]);
56|    expect(model.chapters.flatMap((c) => c.scenes).flatMap((s) => s.paragraphs.map((p) => p.n))).toEqual([1, 2, 3, 4, 5]);
57|  });
58|
59|  it("keeps null emotion for failed scenes", () => {
60|    const model = buildReaderModel(book, { scenes });
61|    expect(model.chapters[0]?.scenes[0]?.emotion).toBeNull();
62|    expect(model.chapters[0]?.scenes[1]?.emotion?.intensity).toBe(0.2);
63|  });
64|
65|  it("drops analysis internals", () => {
66|    const model = buildReaderModel(book, { scenes });
67|    expect(JSON.stringify(model)).not.toContain("muse_override");
68|    expect(JSON.stringify(model)).not.toContain("jev");
69|  });
70|
71|  it("throws on unordered scenes, gaps, overlaps, crossings", () => {
72|    expect(() => buildReaderModel(book, { scenes: [...scenes].reverse() })).toThrow();
73|    const gap = scenes.filter((s) => s.id !== "c1s2");
74|    expect(() => buildReaderModel(book, { scenes: gap })).toThrow();
75|    const overlap = [...scenes];
76|    overlap[1] = scene({ id: "c1s2", start_n: 2, end_n: 3, final: null, error: "x" });
77|    expect(() => buildReaderModel(book, { scenes: overlap })).toThrow();
78|    const cross = [...scenes];
79|    cross[1] = scene({ id: "c1s2", start_n: 3, end_n: 4, final: null, error: "x" });
80|    expect(() => buildReaderModel(book, { scenes: cross })).toThrow();
81|  });
82|});

