1|// Shared music manifest and selection types. Pure: no env, no fetch, no audio.
2|import type { EmotionId, Vector8 } from "./types";
3|
4|// Hand label for the track: the single emotion it was made to carry.
5|export type TrackSource = "generated" | "jamendo" | "recording";
6|
7|export interface Playlist {
8|  id: string;
9|  label: string;
10|  trackIds: string[];
11|}
12|
13|// Fixed id for the owner-requested Chopin playlist. The player button
14|// uses the playlist with this id and shows its label verbatim.
15|export const CHOPIN_PLAYLIST_ID = "just-play-chopin";
16|
17|export interface Track {
18|  id: string;
19|  src: string;
20|  title: string;
21|  playlistOnly?: boolean;
22|  emotion: EmotionId;
23|  vector: Vector8;
24|  intensity: number;
25|  tempo: number;
26|  durationSec: number;
27|  startSec: number;
28|  loop: boolean;
29|  soundtrack: string;
30|  style: string;
31|  source?: TrackSource;
32|  artist?: string;
33|  composer?: string;
34|  license?: string;
35|  attribution?: string;
36|  sourceUrl?: string;
37|}
38|
39|export interface StyleInfo {
40|  id: string;
41|  name: string;
42|}
43|
44|export interface Soundtrack {
45|  id: string;
46|  name: string;
47|  style: string;
48|  credit?: string;
49|}
50|
51|export interface MusicManifest {
52|  version: number;
53|  styles: StyleInfo[];
54|  soundtracks: Soundtrack[];
55|  tracks: Track[];
56|  playlists: Playlist[];
57|}
58|
59|// Session selection: style scopes every pick, soundtrackId is the home
60|// in soundtrack mode, mode picks the ranking rule.
