1|// Player controls: next track, mix toggle, style select, playlist toggle.
2|// No audio here, so the bar layout can change without touching the engine.
3|import type { StyleInfo } from "@/core/music";
4|
5|export function PlayerControls({
6|  canNext,
7|  onNext,
8|  mixOn,
9|  onToggleMix,
10|  styles,
11|  styleId,
12|  onStyleChange,
13|  playlistLabel,
14|  playlistOn,
15|  onTogglePlaylist,
16|  controlsDisabled,
17|}: {
18|  canNext: boolean;
19|  onNext: () => void;
20|  mixOn: boolean;
21|  onToggleMix: () => void;
22|  styles: StyleInfo[];
23|  styleId: string | null;
24|  onStyleChange: (style: string) => void;
25|  playlistLabel: string | null;
26|  playlistOn: boolean;
27|  onTogglePlaylist: () => void;
28|  controlsDisabled: boolean;
29|}) {
30|  return (
31|    <>
32|      <button type="button" onClick={onNext} disabled={!canNext} aria-label="Cambiar track">
33|        Cambiar track
34|      </button>
35|      <button
36|        type="button"
37|        onClick={onToggleMix}
38|        disabled={controlsDisabled}
39|        aria-pressed={mixOn}
40|        aria-label="Mezclar bandas"
41|      >
42|        Mezclar bandas
43|      </button>
44|      {playlistLabel !== null ? (
45|        <button
46|          type="button"
47|          className="chopin"
48|          onClick={onTogglePlaylist}
49|          aria-pressed={playlistOn}
50|        >
51|          {playlistLabel}
52|        </button>
53|      ) : null}
54|      {styles.length >= 2 ? (
55|        <label className="player-note">
56|          Estilo
57|          <select
58|            value={styleId ?? ""}
59|            onChange={(e) => onStyleChange(e.target.value)}
60|            aria-label="Estilo"
61|            disabled={controlsDisabled}
62|          >
63|            {styles.map((s) => (
64|              <option key={s.id} value={s.id}>
65|                {s.name}
66|              </option>
67|            ))}
68|          </select>
69|        </label>
70|      ) : null}
71|    </>
72|  );
73|}

