107|  });
108|  const trackSoundtracks = new Map(soundtracks.map((s) => [s.id, s.style]));
109|  const seenSoundtrack = new Set<string>();
110|  for (const s of soundtracks) {
111|    if (seenSoundtrack.has(s.id)) throw new Error(`duplicate soundtrack id: ${s.id}`);
112|    seenSoundtrack.add(s.id);
113|  }
114|  const tracks = json.tracks.map((entry, i) => {
115|    if (!isRecord(entry)) throw new Error(`track ${i} must be an object`);
116|    const soundtrack: unknown = entry.soundtrack;
117|    const style: unknown = entry.style;
118|    if (typeof soundtrack !== "string" || soundtrack === "") {
119|      throw new Error(`track ${i} needs a soundtrack id`);
120|    }
121|    const home = trackSoundtracks.get(soundtrack);
122|    if (home === undefined) {
