172|function parseTrack(entry: unknown, i: number, soundtrack: string, style: string): Track {
173|  if (!isRecord(entry)) throw new Error(`track ${i} must be an object`);
174|  {
175|    const { id, src, title, emotion, vector, intensity, tempo } = entry;
176|    const { durationSec, startSec, loop, playlistOnly } = entry;
177|    const { source, artist, composer, license, attribution, sourceUrl } = entry;
178|    if (typeof id !== "string" || id === "") throw new Error(`track ${i} needs a string id`);
179|    if (!isSrc(src)) throw new Error(`track ${id} src must be a /music/ path or https URL`);
180|    if (typeof title !== "string" || title === "") throw new Error(`track ${id} needs a title`);
181|    if (!isOneOf(emotion, EMOTIONS)) {
182|      throw new Error(`track ${id} emotion must be one of the 8 emotion ids`);
183|    }
184|    if (!isVector8(vector)) throw new Error(`track ${id} vector must cover the 8 emotion ids`);
185|    if (!isUnit(intensity)) throw new Error(`track ${id} intensity must be 0..1`);
186|    if (!isUnit(tempo)) throw new Error(`track ${id} tempo must be 0..1`);
187|    if (typeof durationSec !== "number" || !Number.isFinite(durationSec) || durationSec <= 0) {
188|      throw new Error(`track ${id} durationSec must be a positive number`);
189|    }
190|    let start = 0;
191|    if (startSec !== undefined) {
192|      if (typeof startSec !== "number" || !Number.isFinite(startSec) || startSec < 0) {
193|        throw new Error(`track ${id} startSec must be >= 0`);
194|      }
195|      if (startSec >= durationSec) {
196|        throw new Error(`track ${id} startSec must be below durationSec`);
197|      }
198|      start = startSec;
199|    }
200|    let loops = true;
201|    if (loop !== undefined) {
202|      if (typeof loop !== "boolean") throw new Error(`track ${id} loop must be a boolean`);
203|      loops = loop;
204|    }
205|    let only = false;
206|    if (playlistOnly !== undefined) {
207|      if (typeof playlistOnly !== "boolean") {
208|        throw new Error(`track ${id} playlistOnly must be a boolean`);
209|      }
210|      only = playlistOnly;
211|    }
212|    let trackSource: TrackSource | undefined;
213|    if (source !== undefined) {
214|      if (!isOneOf(source, SOURCES)) {
215|        throw new Error(`track ${id} source must be generated, jamendo, or recording`);
216|      }
217|      trackSource = source;
218|    }
219|    const credit: { artist?: string; composer?: string; license?: string; attribution?: string } = {};
220|    const pairs = [
221|      ["artist", artist],
222|      ["composer", composer],
223|      ["license", license],
224|      ["attribution", attribution],
225|    ] as const;
226|    for (const [key, value] of pairs) {
227|      if (value === undefined) continue;
228|      if (!isNonEmptyString(value)) throw new Error(`track ${id} ${key} must be a non-empty string`);
229|      credit[key] = value;
230|    }
231|    if (sourceUrl !== undefined && (typeof sourceUrl !== "string" || !sourceUrl.startsWith("https://"))) {
232|      throw new Error(`track ${id} sourceUrl must be an https URL`);
233|    }
234|    return {
235|      id,
236|      src,
237|      title,
238|      playlistOnly: only,
239|      emotion,
240|      vector,
241|      intensity,
242|      tempo,
243|      durationSec,
244|      startSec: start,
245|      loop: loops,
246|      soundtrack,
247|      style,
248|      ...credit,
249|      ...(trackSource === undefined ? {} : { source: trackSource }),
250|      ...(sourceUrl === undefined ? {} : { sourceUrl }),
251|    };
252|  }
253|}

